-- Pack store: one themed pack covers every game. A pack's items are stored
-- per game in the same row shape that game's own table (or trivia's
-- pack_questions) uses, so engines draw from them like built-in content.
-- Items stay service-role only (trivia answers are secret); the catalog is public.

create table public.store_packs (
  id               uuid primary key default gen_random_uuid(),
  slug             text not null unique,
  title            text not null,
  tagline          text not null,
  description      text not null,
  art              text not null,              -- motif key drawn by PackArt
  color            text not null,              -- art background
  accent           text not null,              -- art accent
  tags             text[] not null default '{}',
  price_cents      integer not null check (price_cents >= 0),
  sale_price_cents integer check (sale_price_cents >= 0 and sale_price_cents < price_cents),
  featured         boolean not null default false,
  is_demo          boolean not null default false, -- catalog filler, no content yet
  released_at      date not null default current_date,
  created_at       timestamptz not null default now()
);
alter table public.store_packs enable row level security;
create policy "store_packs: anyone reads" on public.store_packs for select using (true);
grant select on public.store_packs to anon, authenticated;
grant all on public.store_packs to service_role;

create table public.store_pack_items (
  id        uuid primary key default gen_random_uuid(),
  pack_id   uuid not null references public.store_packs (id) on delete cascade,
  game_type text not null check (game_type in ('buzz_trivia', 'wyr', 'mlt', 'hol', 'gtp', 'tank', 'charades', 'num')),
  data      jsonb not null
);
create index store_pack_items_pack_game_idx on public.store_pack_items (pack_id, game_type);
alter table public.store_pack_items enable row level security;
-- no client policies: trivia answers live here
grant all on public.store_pack_items to service_role;

-- what's inside each pack, without exposing the items
create or replace view public.store_pack_counts
  with (security_invoker = off) as
  select pack_id, game_type, count(*)::integer as item_count
  from public.store_pack_items group by pack_id, game_type;
grant select on public.store_pack_counts to anon, authenticated, service_role;

create table public.pack_purchases (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  pack_id     uuid not null references public.store_packs (id) on delete cascade,
  price_cents integer not null,
  -- 'test' until Stripe checkout is wired up
  status      text not null default 'test' check (status in ('test', 'paid', 'refunded')),
  created_at  timestamptz not null default now(),
  unique (user_id, pack_id)
);
alter table public.pack_purchases enable row level security;
create policy "pack_purchases: owner reads" on public.pack_purchases for select using (auth.uid() = user_id);
grant select on public.pack_purchases to authenticated;
grant all on public.pack_purchases to service_role;

